require dirname(__DIR__).'/includes/bootstrap.php';require_once dirname(__DIR__).'/includes/incentive.php';$user=require_staff();$canManage=$user['role_slug']==='administrator';$id=query_id();if(!$id)redirect('admin/incentives.php');$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!$canManage){http_response_code(403);$errors[]='Administrator access is required to confirm distribution.';}elseif(!valid_csrf()){http_response_code(403);$errors[]='The form expired. Reload and try again.';}elseif(post_string('confirm')!=='yes'){$errors[]='Explicit distribution confirmation is required.';http_response_code(422);}else try{$version=filter_var($_POST['status_version']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>0]]);if($version===false)throw new Phase6ConflictException('Reload before continuing.');phase6_distribute(db(),$id,(int)$user['id'],(int)$version,post_string('distribution_notes'));flash('success','Rice distribution was recorded.');redirect('admin/incentive-view.php?id='.$id);}catch(Phase6ValidationException|Phase6ConflictException$e){$errors[]=$e->getMessage();}}
$record=phase6_incentive_record(db(),$id);if(!$record)redirect('admin/incentives.php');$q=db()->prepare("SELECT a.action,a.created_at,u.full_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE a.record_type='incentive_transactions' AND a.record_id=? ORDER BY a.id DESC");$q->execute([$id]);$audits=$q->fetchAll();$q=db()->prepare("SELECT event_code,event_type,description,event_timestamp FROM compliance_ledger WHERE related_record_type='incentive_transactions' AND related_record_id=? ORDER BY id DESC");$q->execute([$id]);$ledger=$q->fetchAll();$pageTitle=$record['transaction_code'];$activeNav='incentives';$flash=consume_flash();require dirname(__DIR__).'/includes/header.php';
?>
<div class="page-heading"><div><div class="breadcrumb"><a href="<?= e(url('admin/incentives.php')) ?>">Incentives</a> <span>/</span> Details</div><h1><?= e($record['transaction_code']) ?></h1><p>Historical calculation snapshot and distribution record.</p></div><span class="status-badge status-<?= e(strtolower(str_replace('_','-',$record['status']))) ?>"><?= e(str_replace('_',' ',$record['status'])) ?></span></div><?php if($flash): ?><div class="notice notice-<?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?><?php foreach($errors as$error): ?><div class="notice notice-error"><?= e($error) ?></div><?php endforeach; ?>
